<?php
declare(strict_types=1);
header('X-Robots-Tag: noindex, nofollow', true);
$configFile=__DIR__.'/catalog-config.php';
$config=is_file($configFile)?require $configFile:null;
function json_out($data,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function cfg_ready($c):bool{return is_array($c)&&!empty($c['supabase_url'])&&!empty($c['publishable_key'])&&!empty($c['admin_token']);}
function supa_rpc(array $c,string $fn,array $body):array{
  $ch=curl_init(rtrim($c['supabase_url'],'/').'/rest/v1/rpc/'.$fn);
  curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>12,CURLOPT_HTTPHEADER=>['apikey: '.$c['publishable_key'],'Content-Type: application/json','Accept: application/json'],CURLOPT_POSTFIELDS=>json_encode($body,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);
  $raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);
  if($raw===false||$err!=='')return ['ok'=>false,'status'=>502,'error'=>$err?:'Connessione Supabase non riuscita'];
  $decoded=json_decode($raw,true);if($code<200||$code>=300)return ['ok'=>false,'status'=>$code,'error'=>is_array($decoded)?($decoded['message']??'Errore Supabase'):$raw];
  return ['ok'=>true,'status'=>$code,'data'=>$decoded];
}
function sanitize_key(string $key):string{$key=trim($key);return preg_match('/^[^\s\x00-\x1F\/\\]{1,80}$/u',$key)?$key:'';}
function upload_logo(array $c):never{
  if(!isset($_FILES['logo'])||!is_uploaded_file($_FILES['logo']['tmp_name']))json_out(['ok'=>false,'error'=>'File logo mancante'],400);
  $key=sanitize_key((string)($_POST['brand_key']??''));if($key==='')json_out(['ok'=>false,'error'=>'Chiave brand non valida'],400);
  if((int)$_FILES['logo']['size']>5*1024*1024)json_out(['ok'=>false,'error'=>'Logo troppo grande: massimo 5 MB'],400);
  $finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($_FILES['logo']['tmp_name']);$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$mime]??null;if(!$ext)json_out(['ok'=>false,'error'=>'Formato logo: PNG, JPG o WebP'],400);
  $publicPath=(string)($c['logo_public_path']??'/assets/catalog-brands');$disk=dirname(__DIR__).$publicPath;if(!is_dir($disk)&&!mkdir($disk,0775,true))json_out(['ok'=>false,'error'=>'Impossibile creare cartella loghi'],500);
  $safe=preg_replace('/[^a-z0-9_-]+/i','-',iconv('UTF-8','ASCII//TRANSLIT',$key)?:$key);$name=strtolower(trim($safe,'-')).'-'.substr(hash_file('sha256',$_FILES['logo']['tmp_name']),0,12).'.'.$ext;
  if(!move_uploaded_file($_FILES['logo']['tmp_name'],$disk.'/'.$name))json_out(['ok'=>false,'error'=>'Salvataggio logo non riuscito'],500);
  $scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$host=$_SERVER['HTTP_HOST']??'fi-card.app';
  json_out(['ok'=>true,'logo_url'=>$scheme.'://'.$host.rtrim($publicPath,'/').'/'.$name]);
}
if(isset($_GET['api'])){
  if(!cfg_ready($config))json_out(['ok'=>false,'error'=>'catalog-config.php non configurato'],503);
  $api=(string)$_GET['api'];
  if($api==='list'){$r=supa_rpc($config,'ficard_admin_catalog',['p_token'=>$config['admin_token']]);json_out($r['ok']?['ok'=>true,'brands'=>$r['data']]:['ok'=>false,'error'=>$r['error']],$r['ok']?200:$r['status']);}
  if($api==='save'&&$_SERVER['REQUEST_METHOD']==='POST'){$payload=json_decode(file_get_contents('php://input'),true);if(!is_array($payload))json_out(['ok'=>false,'error'=>'Payload non valido'],400);$r=supa_rpc($config,'ficard_admin_save_brand',['p_token'=>$config['admin_token'],'p_payload'=>$payload]);json_out($r['ok']?['ok'=>true,'brand'=>$r['data']]:['ok'=>false,'error'=>$r['error']],$r['ok']?200:$r['status']);}
  if($api==='upload'&&$_SERVER['REQUEST_METHOD']==='POST')upload_logo($config);
  json_out(['ok'=>false,'error'=>'Operazione non valida'],404);
}
$markets=is_array($config['implemented_markets']??null)?$config['implemented_markets']:['IT'=>'Italia'];
?><!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Fi-Card Developer · Catalogo</title><style>
:root{--v:#5B3DF5;--t:#2DD4BF;--bg:#f7f8fc;--s:#fff;--tx:#1f2937;--m:#6b7280;--l:#e5e7eb;--d:#dc2626}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:14px Inter,system-ui,sans-serif}header{padding:22px 24px;background:#17152b;color:white;display:flex;justify-content:space-between;align-items:center}header b{font-size:20px}main{max-width:1440px;margin:22px auto;padding:0 18px;display:grid;grid-template-columns:minmax(390px,.9fr) minmax(520px,1.1fr);gap:18px}.box{background:var(--s);border:1px solid var(--l);border-radius:18px;padding:16px}.toolbar{display:grid;grid-template-columns:1fr 150px auto;gap:8px;margin-bottom:12px}.field,input,select{width:100%;border:1px solid var(--l);border-radius:11px;padding:10px;background:#fff}label{display:block;color:var(--m);font-size:12px;font-weight:700;margin:12px 0 5px}.row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.row3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}.btn{border:0;border-radius:11px;padding:10px 13px;font-weight:800;cursor:pointer}.primary{background:var(--v);color:white}.secondary{background:#efecff;color:var(--v)}.list{max-height:76vh;overflow:auto;border-top:1px solid var(--l)}.item{padding:10px 6px;border-bottom:1px solid var(--l);cursor:pointer;display:grid;grid-template-columns:118px 1fr auto;align-items:center;gap:12px}.item:hover{background:#fafaff}.item small{display:block;color:var(--m);margin-top:3px}.mini{height:72px;border-radius:12px;display:flex;align-items:center;justify-content:center;overflow:hidden;border:1px solid rgba(0,0,0,.06);box-shadow:0 3px 10px rgba(31,41,55,.08)}.mini img{max-width:78%;max-height:48px;object-fit:contain}.mini strong{font-size:13px;padding:8px;text-align:center}.badge{font-size:10px;font-weight:900;border-radius:999px;padding:4px 7px;height:max-content;background:#eef2ff;color:#4338ca}.badge.pub{background:#dcfce7;color:#166534}.badge.off{background:#fee2e2;color:#991b1b}.badge.base{background:#fff7ed;color:#9a3412}.markets{display:flex;flex-wrap:wrap;gap:8px;margin-top:7px}.markets label{margin:0;border:1px solid var(--l);border-radius:999px;padding:7px 10px;color:var(--tx);font-weight:700}.markets input{width:auto;margin-right:5px}.status{min-height:20px;color:var(--m);margin:8px 0}.sectionTitle{margin:18px 0 2px;font-weight:900;font-size:15px}.previewWrap{display:grid;grid-template-columns:1fr 170px;gap:10px;align-items:stretch}.preview{border-radius:18px;min-height:150px;padding:18px;margin-top:12px;display:flex;align-items:center;justify-content:center;overflow:hidden;box-shadow:0 8px 24px rgba(31,41,55,.11)}.preview img{max-height:88px;object-fit:contain}.preview strong{font-size:24px;text-align:center}.quickPreview{border-radius:14px;min-height:100px;margin-top:12px;display:flex;align-items:center;justify-content:center;overflow:hidden;box-shadow:0 5px 16px rgba(31,41,55,.09)}.quickPreview img{max-height:55px;object-fit:contain}.quickPreview strong{font-size:16px}.note{background:#f3f4f6;border-radius:12px;padding:10px;color:#4b5563;font-size:12px;margin:10px 0}.configwarn{background:#fff7ed;color:#9a3412;padding:12px;border-radius:12px;margin-bottom:12px}.conditional[hidden]{display:none}.inlineCheck{display:flex;gap:8px;align-items:center;color:var(--tx);font-size:14px}.inlineCheck input{width:auto}.swatch{display:grid;grid-template-columns:52px 1fr;gap:8px}.swatch input[type=color]{height:42px;padding:4px}@media(max-width:920px){main{grid-template-columns:1fr}.list{max-height:46vh}.toolbar{grid-template-columns:1fr 125px}.toolbar .reload{grid-column:1/-1}.previewWrap{grid-template-columns:1fr}.row3{grid-template-columns:1fr}}
</style></head><body><header><div><b>Fi-Card Developer</b><div style="opacity:.7;font-size:12px">Catalogo brand remoto · anteprima e layout</div></div><button class="btn secondary" id="newBtn">＋ Nuovo brand</button></header><main>
<section class="box"><div class="toolbar"><input id="search" placeholder="Cerca brand, chiave, categoria…"><select id="filterState"><option value="">Tutti gli stati</option><option value="published">Pubblicati</option><option value="draft">Bozze</option><option value="disabled">Disattivati</option><option value="base">Solo base app</option></select><button class="btn secondary reload" id="reload">Aggiorna</button></div><div id="count" class="status"></div><div id="list" class="list"></div></section>
<section class="box"><?php if(!cfg_ready($config)):?><div class="configwarn">Manca <b>catalog-config.php</b>. Copia il file di esempio e inserisci il token amministrativo del catalogo.</div><?php endif;?>
<div id="legacyNote" class="note" hidden>Questa è ancora una scheda base incorporata nell’app. Salvandola qui, il catalogo server diventa autorevole per questo brand.</div>
<div class="sectionTitle">Identità del brand</div>
<div class="row"><div><label>Chiave brand</label><input id="key" placeholder="es. conad"></div><div><label>Nome visualizzato</label><input id="name" placeholder="es. Conad"></div></div>
<div class="row"><div><label>Categoria</label><select id="category"><option value="supermercati">Supermercati</option><option value="abbigliamento">Abbigliamento</option><option value="sport">Sport</option><option value="elettronica">Elettronica</option><option value="casa">Casa / bricolage</option><option value="casalinghi">Casalinghi</option><option value="petstore">Pet store</option><option value="farmacia">Farmacia</option><option value="beauty">Beauty</option><option value="ristorazione">Ristorazione</option><option value="carburanti">Carburanti</option><option value="altro">Altro</option></select></div><div><label>Stato</label><select id="state"><option value="draft">Bozza</option><option value="published">Pubblicato</option><option value="disabled">Disattivato</option></select></div></div>
<div class="row"><div><label>Sigla / fallback</label><input id="mark" placeholder="CONAD"></div><div><label>Dominio ufficiale</label><input id="domain" placeholder="conad.it"></div></div>
<div class="sectionTitle">Logo</div><label>Logo pubblico</label><div class="row"><input id="logo" placeholder="https://…"><input id="logoFile" type="file" accept="image/png,image/jpeg,image/webp"></div><button class="btn secondary" id="uploadBtn" type="button" style="margin-top:8px">Carica logo</button><label>Scala logo <span id="scaleOut">70%</span></label><input id="scale" type="range" min="10" max="100" value="70">
<div class="sectionTitle">Layout tessera</div>
<div class="row"><div><label>Tipo layout</label><select id="layoutType"><option value="solid">Tinta unita</option><option value="split_horizontal">Bicolore orizzontale · sinistra/destra</option><option value="split_vertical">Bicolore verticale · alto/basso</option><option value="gradient_linear">Gradiente lineare</option><option value="gradient_elliptical">Gradiente ellittico</option><option value="gradient_radial">Gradiente sferico</option></select></div><div class="conditional" id="ratioBox"><label>Rapporto</label><select id="splitRatio"><option value="33">33 / 66</option><option value="50" selected>50 / 50</option><option value="66">66 / 33</option></select></div></div>
<div class="row"><div><label>Colore 1</label><div class="swatch"><input id="color" type="color" value="#5B3DF5"><input id="colorHex" value="#5B3DF5" maxlength="7"></div></div><div class="conditional" id="color2Box"><label>Colore 2</label><div class="swatch"><input id="color2" type="color" value="#2DD4BF"><input id="color2Hex" value="#2DD4BF" maxlength="7"></div></div></div>
<div class="conditional" id="linearBox"><label>Direzione gradiente</label><select id="gradientDirection"><option value="left_right">Sinistra → destra</option><option value="right_left">Destra → sinistra</option><option value="top_bottom">Alto → basso</option><option value="bottom_top">Basso → alto</option><option value="diag_down">Diagonale ↘</option><option value="diag_up">Diagonale ↗</option></select></div>
<div class="conditional row3" id="radialBox"><div><label>Centro X <span id="cxOut">50%</span></label><input id="centerX" type="range" min="0" max="100" value="50"></div><div><label>Centro Y <span id="cyOut">50%</span></label><input id="centerY" type="range" min="0" max="100" value="50"></div><div><label>Ampiezza <span id="softOut">70%</span></label><input id="softness" type="range" min="20" max="100" value="70"></div></div>
<div class="previewWrap"><div class="preview" id="preview"><strong>ANTEPRIMA</strong></div><div class="quickPreview" id="quickPreview"><strong>MINI</strong></div></div>
<div class="sectionTitle">Mercato</div><label class="inlineCheck"><input id="international" type="checkbox" checked> Internazionale · disponibile in tutti i mercati implementati</label><div class="markets" id="markets"><?php foreach($markets as $code=>$label):?><label><input type="checkbox" value="<?=htmlspecialchars($code)?>"> <?=htmlspecialchars($label)?> <small><?=htmlspecialchars($code)?></small></label><?php endforeach;?></div>
<div class="row"><div><label>Revisione</label><input id="revision" value="—" disabled></div><div><label>Ultimo aggiornamento</label><input id="updatedAt" value="—" disabled></div></div>
<div id="msg" class="status"></div><button class="btn primary" id="saveBtn" style="width:100%">Salva scheda</button>
</section></main><script>
const $=id=>document.getElementById(id), marketChecks=[...document.querySelectorAll('#markets input')];let brands=[],editing=null;
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function badge(b){if(!b.is_complete)return '<span class="badge base">BASE APP</span>';if(b.status==='published')return '<span class="badge pub">PUBBLICATO</span>';if(b.status==='disabled')return '<span class="badge off">DISATTIVATO</span>';return '<span class="badge">BOZZA</span>'}
const dirMap={left_right:'to right',right_left:'to left',top_bottom:'to bottom',bottom_top:'to top',diag_down:'135deg',diag_up:'45deg'};
function bgFor(b){const c1=b.color||'#5B3DF5',c2=b.color_2||'#2DD4BF',t=b.layout_type||'solid',r=Number(b.split_ratio||50),x=Number(b.gradient_center_x??50),y=Number(b.gradient_center_y??50),s=Number(b.gradient_softness??70);if(t==='split_horizontal')return `linear-gradient(to right,${c1} 0 ${r}%,${c2} ${r}% 100%)`;if(t==='split_vertical')return `linear-gradient(to bottom,${c1} 0 ${r}%,${c2} ${r}% 100%)`;if(t==='gradient_linear')return `linear-gradient(${dirMap[b.gradient_direction]||'to right'},${c1},${c2})`;if(t==='gradient_elliptical')return `radial-gradient(ellipse at ${x}% ${y}%,${c1} 0%,${c2} ${s}%)`;if(t==='gradient_radial')return `radial-gradient(circle at ${x}% ${y}%,${c1} 0%,${c2} ${s}%)`;return c1}
function logoHtml(b,mini=false){const name=b.name||b.mark||b.brand_key||'ANTEPRIMA',url=b.logo_url||'',scale=Math.max(10,Math.min(100,Number(b.logo_scale||70)));return url?`<img alt="${esc(name)}" src="${esc(url)}" style="width:${scale}%" onerror="this.style.display='none';this.nextElementSibling.style.display='block'"><strong style="display:none">${esc(name)}</strong>`:`<strong>${esc(name)}</strong>`}
function renderList(){const q=$('search').value.trim().toLowerCase(),f=$('filterState').value;const rows=brands.filter(b=>(!q||[b.brand_key,b.name,b.category,(b.markets||[]).join(' ')].join(' ').toLowerCase().includes(q))&&(!f||(f==='base'?!b.is_complete:b.status===f)));$('count').textContent=rows.length+' schede';$('list').innerHTML=rows.map(b=>`<div class="item" data-k="${esc(b.brand_key)}"><div class="mini" style="background:${bgFor(b)}">${logoHtml(b,true)}</div><div><b>${esc(b.is_complete?b.name:b.brand_key)}</b><small>${esc(b.brand_key)} · ${esc(b.category||'altro')}${b.international?' · internazionale':' · '+esc((b.markets||[]).join(', '))}</small></div>${badge(b)}</div>`).join('');document.querySelectorAll('.item').forEach(x=>x.onclick=()=>edit(x.dataset.k))}
function setHex(colorId,hexId,value){const v=/^#[0-9a-f]{6}$/i.test(value||'')?value:'#5B3DF5';$(colorId).value=v;$(hexId).value=v.toUpperCase()}
function blank(){editing=null;$('key').disabled=false;$('key').value='';$('name').value='';$('category').value='altro';setHex('color','colorHex','#5B3DF5');setHex('color2','color2Hex','#2DD4BF');$('mark').value='';$('domain').value='';$('logo').value='';$('scale').value=70;$('state').value='draft';$('revision').value='—';$('updatedAt').value='—';$('international').checked=true;marketChecks.forEach(x=>x.checked=false);$('layoutType').value='solid';$('splitRatio').value='50';$('gradientDirection').value='left_right';$('centerX').value=50;$('centerY').value=50;$('softness').value=70;$('legacyNote').hidden=true;marketMode();layoutMode();preview()}
function edit(k){const b=brands.find(x=>x.brand_key===k);if(!b)return;editing=b;$('key').disabled=true;$('key').value=b.brand_key;$('name').value=b.is_complete?b.name:b.brand_key;$('category').value=b.category||'altro';setHex('color','colorHex',b.color||'#5B3DF5');setHex('color2','color2Hex',b.color_2||'#2DD4BF');$('mark').value=b.mark||'';$('domain').value=b.domain||'';$('logo').value=b.logo_url||'';$('scale').value=b.logo_scale||70;$('state').value=b.status||'draft';$('revision').value=b.revision||1;$('updatedAt').value=b.updated_at?new Date(b.updated_at).toLocaleString('it-IT'):'—';$('international').checked=b.international!==false;marketChecks.forEach(x=>x.checked=(b.markets||[]).includes(x.value));$('layoutType').value=b.layout_type||'solid';$('splitRatio').value=String(b.split_ratio||50);$('gradientDirection').value=b.gradient_direction||'left_right';$('centerX').value=b.gradient_center_x??50;$('centerY').value=b.gradient_center_y??50;$('softness').value=b.gradient_softness??70;$('legacyNote').hidden=!!b.is_complete;marketMode();layoutMode();preview();scrollTo({top:0,behavior:'smooth'})}
function marketMode(){const off=$('international').checked;marketChecks.forEach(x=>x.disabled=off)}
function layoutMode(){const t=$('layoutType').value,isSplit=t.startsWith('split_'),isLinear=t==='gradient_linear',isRadial=t==='gradient_elliptical'||t==='gradient_radial';$('ratioBox').hidden=!isSplit;$('color2Box').hidden=t==='solid';$('linearBox').hidden=!isLinear;$('radialBox').hidden=!isRadial}
function currentModel(){return{brand_key:$('key').value.trim(),name:$('name').value.trim(),category:$('category').value,color:$('color').value.toUpperCase(),color_2:$('layoutType').value==='solid'?null:$('color2').value.toUpperCase(),mark:$('mark').value.trim()||null,domain:$('domain').value.trim()||null,logo_url:$('logo').value.trim()||null,logo_bg:'transparent',logo_scale:Number($('scale').value),international:$('international').checked,markets:marketChecks.filter(x=>x.checked).map(x=>x.value),status:$('state').value,layout_type:$('layoutType').value,split_ratio:Number($('splitRatio').value),gradient_direction:$('gradientDirection').value,gradient_center_x:Number($('centerX').value),gradient_center_y:Number($('centerY').value),gradient_softness:Number($('softness').value)}}
function preview(){const m=currentModel();$('preview').style.background=bgFor(m);$('quickPreview').style.background=bgFor(m);$('scaleOut').textContent=m.logo_scale+'%';$('cxOut').textContent=m.gradient_center_x+'%';$('cyOut').textContent=m.gradient_center_y+'%';$('softOut').textContent=m.gradient_softness+'%';$('preview').innerHTML=logoHtml(m);$('quickPreview').innerHTML=logoHtml({...m,logo_scale:Math.min(m.logo_scale,75)},true)}
async function load(){ $('msg').textContent='Carico catalogo…';try{const r=await fetch('?api=list',{credentials:'same-origin',cache:'no-store'}),j=await r.json();if(!j.ok)throw new Error(j.error||'Errore');brands=Array.isArray(j.brands)?j.brands:[];renderList();$('msg').textContent=''}catch(e){$('msg').textContent=e.message}}
async function upload(){const f=$('logoFile').files[0],key=$('key').value.trim();if(!f||!key){$('msg').textContent='Inserisci prima la chiave brand e scegli il logo.';return}const fd=new FormData();fd.append('brand_key',key);fd.append('logo',f);$('msg').textContent='Carico logo…';try{const r=await fetch('?api=upload',{method:'POST',body:fd,credentials:'same-origin'}),j=await r.json();if(!j.ok)throw new Error(j.error||'Upload non riuscito');$('logo').value=j.logo_url;preview();$('msg').textContent='Logo caricato.'}catch(e){$('msg').textContent=e.message}}
async function save(){const p=currentModel();if(!p.brand_key||!p.name){$('msg').textContent='Chiave e nome sono obbligatori.';return}if(!p.international&&!p.markets.length){$('msg').textContent='Seleziona almeno un mercato.';return}$('saveBtn').disabled=true;$('msg').textContent='Salvo…';try{const r=await fetch('?api=save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p),credentials:'same-origin'}),j=await r.json();if(!j.ok)throw new Error(j.error||'Salvataggio non riuscito');$('msg').textContent='Scheda salvata e catalogo aggiornato.';await load();edit(p.brand_key)}catch(e){$('msg').textContent=e.message}finally{$('saveBtn').disabled=false}}
$('newBtn').onclick=blank;$('reload').onclick=load;$('search').oninput=renderList;$('filterState').onchange=renderList;$('international').onchange=()=>{marketMode();preview()};$('layoutType').onchange=()=>{layoutMode();preview()};$('uploadBtn').onclick=upload;$('saveBtn').onclick=save;
['name','mark','logo','scale','splitRatio','gradientDirection','centerX','centerY','softness'].forEach(id=>$(id).addEventListener('input',preview));
[['color','colorHex'],['color2','color2Hex']].forEach(([c,h])=>{$(c).addEventListener('input',()=>{$(h).value=$(c).value.toUpperCase();preview()});$(h).addEventListener('change',()=>{if(/^#[0-9a-f]{6}$/i.test($(h).value)){$(c).value=$(h).value;$(h).value=$(h).value.toUpperCase();preview()}})});
blank();load();
</script></body></html>